resource storageAccount 'Microsoft.Storage/storageAccounts@2023-05-01' = {
  name: 'mystorage${uniqueString(resourceGroup().id)}'
  location: resourceGroup().location
  sku: { name: 'Standard_LRS' }
  kind: 'StorageV2'
}

// The storageAccount.id reference creates an implicit dependency
// Bicep will deploy storageAccount before keyVault
resource keyVault 'Microsoft.KeyVault/vaults@2023-07-01' = {
  name: 'my-keyvault-${uniqueString(resourceGroup().id)}'
  location: resourceGroup().location
  properties: {
    tenantId: subscription().tenantId
    sku: {
      name: 'standard'
      family: 'A'
    }
  }
}

// keyVault depends on storageAccount because we reference storageAccount.id
resource keyVaultAccessPolicy 'Microsoft.KeyVault/vaults/accessPolicies@2023-07-01' = {
  name: '${keyVault.name}/add'
  properties: {
    accessPolicies: [
      {
        tenantId: subscription().tenantId
        objectId: '00000000-0000-0000-0000-000000000000'
        permissions: {
          secrets: ['get', 'list']
        }
      }
    ]
  }
  dependsOn: [
    keyVault
  ]
}

resource appServicePlan 'Microsoft.Web/serverfarms@2023-12-01' = {
  name: 'my-plan'
  location: resourceGroup().location
  sku: {
    name: 'S1'
    capacity: 1
  }
  kind: 'app'
}

resource webApp 'Microsoft.Web/sites@2023-12-01' = {
  name: 'my-web-app'
  location: resourceGroup().location
  properties: {
    serverFarmId: appServicePlan.id
  }
  dependsOn: [
    appServicePlan
  ]
}
